'use client';

import { useLayoutEffect, useEffect, useRef, useState } from 'react';
import { usePointerDrag } from './use-pointer-drag';
import { useReducedMotion } from './use-reduced-motion';
import './drag-reorder-list.css';

export interface ReorderItem {
  id: string;
  label: string;
}

export interface DragReorderListProps {
  items: ReorderItem[];
  onReorder: (items: ReorderItem[]) => void;
  /** Accessible name for the list. */
  label: string;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

const move = <T,>(list: T[], from: number, to: number) => {
  const next = [...list];
  const [item] = next.splice(from, 1);
  next.splice(to, 0, item);
  return next;
};

/**
 * Drag a row by its handle; the other rows slide aside to show where it will
 * land. Every row also has Move up and Move down buttons, and each move is
 * announced with the new position.
 */
export function DragReorderList({
  items,
  onReorder,
  label,
  className = '',
}: DragReorderListProps) {
  const list = useRef<HTMLOListElement>(null);
  const [drag, setDrag] = useState<{
    from: number;
    to: number;
    dy: number;
    slot: number;
  } | null>(null);
  const [message, setMessage] = useState('');
  const dragRef = useRef(drag);
  dragRef.current = drag;
  const dropped = useRef<{ id: string; offset: number } | null>(null);
  const focusAfter = useRef<string | null>(null);
  const reduced = useReducedMotion();

  // Settle the dropped row from where it was let go.
  useIsomorphicLayoutEffect(() => {
    const done = dropped.current;
    dropped.current = null;
    if (done && !reduced) {
      const el = list.current?.querySelector<HTMLElement>(
        `[data-id="${done.id}"]`
      );
      el?.animate?.(
        [{ transform: `translateY(${done.offset}px)` }, { transform: 'none' }],
        {
          duration: 220,
          easing: 'cubic-bezier(0.2, 0.8, 0.2, 1)',
        }
      );
    }
    if (focusAfter.current) {
      list.current?.querySelector<HTMLElement>(focusAfter.current)?.focus();
      focusAfter.current = null;
    }
  }, [items]);

  const commit = (from: number, to: number) => {
    if (from === to) return;
    const next = move(items, from, to);
    onReorder(next);
    setMessage(
      `Moved “${items[from].label}” to position ${to + 1} of ${items.length}.`
    );
  };

  // One drag controller for the whole list; the handle tells it which row.
  const active = useRef(0);
  const dragger = usePointerDrag({
    onStart: (event) => {
      const row = (event.currentTarget as HTMLElement).closest<HTMLElement>(
        '[data-index]'
      );
      if (!row) return false;
      active.current = Number(row.dataset.index);
      const slot =
        row.offsetHeight +
        parseFloat(getComputedStyle(list.current!).rowGap || '0');
      setDrag({ from: active.current, to: active.current, dy: 0, slot });
    },
    onMove: ({ dy }) =>
      setDrag((d) =>
        d
          ? {
              ...d,
              dy,
              to: Math.max(
                0,
                Math.min(items.length - 1, d.from + Math.round(dy / d.slot))
              ),
            }
          : d
      ),
    onEnd: () => {
      const d = dragRef.current;
      setDrag(null);
      if (!d) return;
      dropped.current = {
        id: items[d.from].id,
        offset: d.dy - (d.to - d.from) * d.slot,
      };
      commit(d.from, d.to);
    },
  });

  const shift = (index: number) => {
    if (!drag || index === drag.from) return 0;
    if (drag.from < drag.to && index > drag.from && index <= drag.to)
      return -drag.slot;
    if (drag.from > drag.to && index < drag.from && index >= drag.to)
      return drag.slot;
    return 0;
  };

  return (
    <div className={`mg-reorder ${className}`} data-dragging={drag !== null}>
      <ol ref={list} className='mg-reorder__list' aria-label={label}>
        {items.map((item, index) => {
          const dragging = drag?.from === index;
          return (
            <li
              key={item.id}
              data-id={item.id}
              data-index={index}
              data-dragging={dragging}
              className='mg-reorder__row'
              style={{
                transform: `translateY(${dragging ? drag!.dy : shift(index)}px)`,
              }}
            >
              <span
                className='mg-reorder__handle'
                aria-hidden='true'
                title='Drag to reorder'
                {...dragger}
              >
                ⋮⋮
              </span>
              <span className='mg-reorder__label'>{item.label}</span>
              <button
                type='button'
                className='mg-reorder__move'
                data-move='up'
                aria-label={`Move ${item.label} up`}
                disabled={index === 0}
                onClick={() => {
                  focusAfter.current = `[data-id="${item.id}"] [data-move="${index - 1 === 0 ? 'down' : 'up'}"]`;
                  commit(index, index - 1);
                }}
              >
                ↑
              </button>
              <button
                type='button'
                className='mg-reorder__move'
                data-move='down'
                aria-label={`Move ${item.label} down`}
                disabled={index === items.length - 1}
                onClick={() => {
                  focusAfter.current = `[data-id="${item.id}"] [data-move="${index + 1 === items.length - 1 ? 'up' : 'down'}"]`;
                  commit(index, index + 1);
                }}
              >
                ↓
              </button>
            </li>
          );
        })}
      </ol>
      <p className='mg-reorder__status' role='status'>
        {message}
      </p>
    </div>
  );
}

.mg-reorder__list {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mg-reorder__row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 48px;
  padding: 0 4px 0 0;
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 10px;
  background: #fff;
  color: var(--mg-ink, #0c1738);
  transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-reorder[data-dragging='false'] .mg-reorder__row {
  transition: none;
}

.mg-reorder__row[data-dragging='true'] {
  z-index: 2;
  border-color: var(--mg-accent, #164cff);
  box-shadow: 0 14px 28px -14px rgba(12, 23, 56, 0.55);
  transition: none;
}

.mg-reorder__handle {
  display: grid;
  place-items: center;
  align-self: stretch;
  width: 36px;
  color: #8a96bd;
  letter-spacing: -2px;
  cursor: grab;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

.mg-reorder__row[data-dragging='true'] .mg-reorder__handle {
  cursor: grabbing;
}

.mg-reorder__label {
  flex: 1;
  min-width: 0;
  font-weight: 600;
}

.mg-reorder__move {
  width: 40px;
  height: 40px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--mg-accent, #164cff);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.mg-reorder__move:hover {
  background: #e6ecff;
}

.mg-reorder__move:disabled {
  color: #c3cbe0;
  cursor: default;
  background: none;
}

.mg-reorder__move:focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: -2px;
}

.mg-reorder__status {
  min-height: 1.3em;
  margin: 8px 0 0;
  color: #46527a;
  font-size: 13px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-reorder__row {
    transition: none;
  }
}

'use client';

import { useRef, type PointerEvent as ReactPointerEvent } from 'react';

export interface DragState {
  /** Distance from where the drag started, in pixels. */
  dx: number;
  dy: number;
  /** Pointer position in viewport coordinates. */
  clientX: number;
  clientY: number;
  /** Smoothed velocity in pixels per millisecond. */
  vx: number;
  vy: number;
}

export interface PointerDragOptions {
  /** Return false to ignore this press. */
  onStart?: (event: ReactPointerEvent<HTMLElement>) => boolean | void;
  onMove?: (drag: DragState) => void;
  /**
   * `cancelled` is true when the browser took the gesture over, for example
   * to scroll the page on touch.
   */
  onEnd?: (drag: DragState, cancelled: boolean) => void;
}

interface Active {
  id: number;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  lastTime: number;
  vx: number;
  vy: number;
}

/**
 * Pointer-capture dragging for mouse, pen and touch. Spread the returned
 * handlers on the element that starts the drag. Pair it with a CSS
 * `touch-action` that leaves the scroll axis you still want to the browser.
 */
export function usePointerDrag(options: PointerDragOptions) {
  const latest = useRef(options);
  latest.current = options;
  const active = useRef<Active | null>(null);

  const snapshot = (a: Active, x: number, y: number): DragState => ({
    dx: x - a.startX,
    dy: y - a.startY,
    clientX: x,
    clientY: y,
    vx: a.vx,
    vy: a.vy,
  });

  const finish = (
    event: ReactPointerEvent<HTMLElement>,
    cancelled: boolean
  ) => {
    const a = active.current;
    if (!a || a.id !== event.pointerId) return;
    active.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
    // A pause before release means the pointer was not really flung.
    if (event.timeStamp - a.lastTime > 150) {
      a.vx = 0;
      a.vy = 0;
    }
    latest.current.onEnd?.(
      snapshot(a, event.clientX, event.clientY),
      cancelled
    );
  };

  return {
    onPointerDown(event: ReactPointerEvent<HTMLElement>) {
      if (event.button !== 0 || active.current) return;
      if (latest.current.onStart?.(event) === false) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      active.current = {
        id: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        lastTime: event.timeStamp,
        vx: 0,
        vy: 0,
      };
    },
    onPointerMove(event: ReactPointerEvent<HTMLElement>) {
      const a = active.current;
      if (!a || a.id !== event.pointerId) return;
      const dt = Math.max(1, event.timeStamp - a.lastTime);
      a.vx = a.vx * 0.6 + ((event.clientX - a.lastX) / dt) * 0.4;
      a.vy = a.vy * 0.6 + ((event.clientY - a.lastY) / dt) * 0.4;
      a.lastX = event.clientX;
      a.lastY = event.clientY;
      a.lastTime = event.timeStamp;
      latest.current.onMove?.(snapshot(a, event.clientX, event.clientY));
    },
    onPointerUp(event: ReactPointerEvent<HTMLElement>) {
      finish(event, false);
    },
    onPointerCancel(event: ReactPointerEvent<HTMLElement>) {
      finish(event, true);
    },
  };
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
